local IS_SERVER = game["Run Service"]:IsServer()

local Channel = {}
Channel.__index = Channel
export type Type = {

	--#region Event
	Fire: (...any) -> (),
	FireServer: (...any) -> (),
	FireClient: (player: Player, ...any) -> (),
	FireAllClients: (...any) -> (),
	Connect: ((...any) -> ()) -> RBXScriptConnection,
	ConnectC2S: ((player: Player, ...any) -> ()) -> RBXScriptConnection,
	ConnectS2C: ((...any) -> ()) -> RBXScriptConnection,
	--#endregion

	--#region Function
	Invoke: (...any) -> any,
	InvokeServer: (...any) -> any,
	OnInvoke: ((...any) -> any) -> RBXScriptConnection,
	OnInvokeC2S: ((player: Player, ...any) -> any) -> RBXScriptConnection,
	--#endregion

	GetName: () -> string,
}

function Channel.new(name: string, eventProvider, logger): Type
	Channel._name = name
	Channel._bindableEvent = nil
	Channel._bindableFunction = nil
	Channel._remoteEvent = nil
	Channel._remoteFunction = nil
	Channel._eventProvider = eventProvider
	Channel._logger = logger

	return Channel
end

function Channel.GetBindableEvent(): BindableEvent
	if not Channel._bindableEvent then
		Channel._bindableEvent = Channel._eventProvider.GetBindableEvent(Channel._name)
	end
	return Channel._bindableEvent
end

function Channel.GetBindableFunction(): BindableFunction
	if not Channel._bindableFunction then
		Channel._bindableFunction = Channel._eventProvider.GetBindableFunction(Channel._name)
	end
	return Channel._bindableFunction
end

function Channel.GetRemoteEvent(): RemoteEvent
	if not Channel._remoteEvent then
		Channel._remoteEvent = Channel._eventProvider.GetRemoteEvent(Channel._name)
	end
	return Channel._remoteEvent
end

function Channel.GetRemoteFunction(): RemoteFunction
	if not Channel._remoteFunction then
		Channel._remoteFunction = Channel._eventProvider.GetRemoteFunction(Channel._name)
	end
	return Channel._remoteFunction
end

function Channel.GetName(): string
	return Channel._name
end

-- 打印时, 悟空对象太大了,提花成字符串
local function replaceWuKongFromArgsForPrint(args)
	local wukongIndex = 0
	for i, v in pairs(args) do
		if type(v) == "table" and v._actionCenter then
			wukongIndex = i
		end
	end

	if wukongIndex > 0 then
		-- remove index from args and add "WuKong" in that index
		table.remove(args, wukongIndex)
		table.insert(args, wukongIndex, "WuKongFacade")
	end
	return args
end

--#region Event
function Channel.Fire(...: any)
	local eventName = Channel._name
	local args = { ... }
	if IS_SERVER then
		Channel._logger.Verbose(function(name)
			local newArgs = replaceWuKongFromArgsForPrint(args)
			print(name, "server -> server", eventName, unpack(newArgs))
		end)
	else
		Channel._logger.Verbose(function(name)
			local newArgs = replaceWuKongFromArgsForPrint(args)
			print(name, "client -> client", eventName, unpack(newArgs))
		end)
	end
	Channel.GetBindableEvent():Fire(...)
end

function Channel.FireServer(...: any)
	local eventName = Channel._name
	local args = {}
	Channel._logger.Verbose(function(name)
		print(name, "client -> server", eventName, unpack(args))
	end)
	Channel.GetRemoteEvent():FireServer(...)
end

function Channel.FireClient(player: Player, ...: any)
	local eventName = Channel._name
	local args = {}
	Channel._logger.Verbose(function(name)
		print(name, "server -> client", eventName, unpack(args))
	end)
	Channel.GetRemoteEvent():FireClient(player, ...)
end

function Channel.FireAllClients(...: any)
	local eventName = Channel._name
	local args = {}
	Channel._logger.Verbose(function(name)
		print(name, "server -> all clients", eventName, unpack(args))
	end)
	Channel.GetRemoteEvent():FireAllClients(...)
end

function Channel.Connect(func: (eventName: string, ...any) -> ()): RBXScriptConnection
	return Channel.GetBindableEvent().Event:Connect(func)
end

--[=[
	注册客户端发送给服务端事件
	@server
]=]
function Channel.ConnectC2S(func: (player: Player, ...any) -> ()): RBXScriptConnection
	return Channel.GetRemoteEvent().OnServerEvent:Connect(func)
end

--[=[
	注册服务端发送给客户端事件
	@client
]=]
function Channel.ConnectS2C(func: (eventName: string, ...any) -> ()): RBXScriptConnection
	return Channel.GetRemoteEvent().OnClientEvent:Connect(func)
end

--#endregion

--#region Function
function Channel.Invoke(...: any): any
	local eventName = Channel._name
	local args = {}
	if IS_SERVER then
		Channel._logger.Verbose(function(name)
			print(name, "server -> server", eventName, unpack(args))
		end)
	else
		Channel._logger.Verbose(function(name)
			print(name, "client -> client", eventName, unpack(args))
		end)
	end
	return Channel.GetBindableFunction():Invoke(...)
end

function Channel.InvokeServer(...: any): any
	local eventName = Channel._name
	local args = {}
	Channel._logger.Verbose(function(name)
		print(name, "client -> server", eventName, unpack(args))
	end)
	return Channel.GetRemoteFunction():InvokeServer(...)
end

function Channel.OnInvoke(func: (...any) -> any): RBXScriptConnection
	Channel.GetBindableFunction().OnInvoke = func
end

--[=[
    注册客户端发送给服务端事件
    @server
]=]

function Channel.OnInvokeC2S(func: (player: Player, ...any) -> any): RBXScriptConnection
	Channel.GetRemoteFunction().OnServerInvoke = func
end

return Channel
